import bmesh
def split_boundary_fans(name=None, where=None):
    """Give every boundary vertex degree 2 by splitting its face fan into separate corners.

    A boundary vertex with 4 boundary edges is TWO corners sharing one vertex — the surface
    pinches to a point there. Extruding such a boundary makes four faces share an edge, which is
    what took non-manifold from 0 to 22 on the first rim attempt.

    Faces around the vertex are grouped by whether they are reachable through a NON-boundary edge;
    each group after the first gets its own copy of the vertex. That is the general form of the
    hand-rolled rip done earlier, and unlike it, it terminates with every boundary vertex at
    degree exactly 2.
    """
    o = obj(name)
    bm = bmesh.new(); bm.from_mesh(o.data)
    bm.verts.ensure_lookup_table()
    made = 0
    for v in list(bm.verts):
        bnd = [e for e in v.link_edges if len(e.link_faces) == 1]
        if len(bnd) <= 2:
            continue
        if where and not where(v.co):
            continue
        fs = list(v.link_faces)
        if len(fs) < 2:
            continue
        parent = {f: f for f in fs}
        def find(f):
            while parent[f] is not f:
                parent[f] = parent[parent[f]]; f = parent[f]
            return f
        for e in v.link_edges:
            if len(e.link_faces) == 2:
                a, b = e.link_faces
                if a in parent and b in parent:
                    parent[find(a)] = find(b)
        groups = {}
        for f in fs:
            groups.setdefault(find(f), []).append(f)
        if len(groups) < 2:
            continue
        for grp in list(groups.values())[1:]:
            nv = bm.verts.new(v.co.copy())
            rebuild = [[nv if x is v else x for x in f.verts] for f in grp]
            bmesh.ops.delete(bm, geom=grp, context="FACES")
            for vl in rebuild:
                try: bm.faces.new(vl)
                except ValueError: pass
            made += 1
        bm.verts.ensure_lookup_table()
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(o.data); bm.free(); o.data.update()
    return made
globals()["split_boundary_fans"]=split_boundary_fans
n = split_boundary_fans(where=lambda p: p.y<-0.15 and 0.68<p.z<0.77)
result={"corners_split":n, "stat":stat()}

