def densify(pts, n=8):
    r = []
    for i in range(len(pts) - 1):
        a, b = Vector(pts[i]), Vector(pts[i + 1])
        for k in range(n): r.append(a.lerp(b, k / n))
    r.append(Vector(pts[-1])); return r

