    poly = PRr if p.x >= 0 else PLl
    best = 1e9
    for i in range(len(poly) - 1):
        a, b = poly[i], poly[i + 1]; ab = b - a
        t = max(0.0, min(1.0, (p - a).dot(ab) / max(ab.length_squared, 1e-12)))
        best = min(best, (p - (a + ab * t)).length)
    return best

