# STEP 1 of the mouth rebuild: excise the tangled region cleanly.
#
# The tangle is a PARTIALLY WELDED DOUBLED SURFACE -- coincident quads with
# opposite normals sharing 2 of 4 verts. Four repair attempts (weld 6e-4,
# weld 1e-6, delete duplicate sheets, weld+dedupe) all tore the neighbourhood
# because the two copies attach to their surroundings differently. So the
# region gets cut out and rebuilt rather than repaired in place.
#
# This script only CUTS and reports the boundary. It does not rebuild.
import math, collections

RINGS = 2          # buffer rings beyond the measurably-bad faces


def _region(c):
    return abs(c.x) < 0.12 and c.y < -0.15 and 0.66 < c.z < 0.80


o = bpy.data.objects["clyffy_mesh"]
if o.mode != "EDIT":
    for ob in bpy.data.objects:
        ob.select_set(False)
    bpy.context.view_layer.objects.active = o
    o.select_set(True)
    bpy.ops.object.mode_set(mode="EDIT")

bm = bmesh.from_edit_mesh(o.data)
bm.verts.ensure_lookup_table(); bm.faces.ensure_lookup_table()
bm.edges.ensure_lookup_table()

MED = 2.947e-05
bad = set()

# doubled verts
g = collections.defaultdict(list)
for v in bm.verts:
    if _region(v.co):
        g[tuple(round(c, 6) for c in v.co)].append(v.index)
dv = {i for p in g.values() if len(p) > 1 for i in p}
for i in dv:
    bad.update(f.index for f in bm.verts[i].link_faces)

# folded edges and flipped-normal neighbours
for e in bm.edges:
    if len(e.link_faces) != 2:
        continue
    if not _region((e.verts[0].co + e.verts[1].co) / 2):
        continue
    a = abs(math.degrees(e.calc_face_angle_signed(0.0)))
    if a > 100 or e.link_faces[0].normal.dot(e.link_faces[1].normal) < -0.3:
        bad.update(f.index for f in e.link_faces)

# slivers
for f in bm.faces:
    if _region(f.calc_center_median()) and f.calc_area() < MED * 0.15:
        bad.add(f.index)

core = len(bad)

# grow by RINGS, staying inside the mouth region
for _ in range(RINGS):
    add = set()
    for i in list(bad):
        for e in bm.faces[i].edges:
            for h in e.link_faces:
                if h.index not in bad and _region(h.calc_center_median()):
                    add.add(h.index)
    bad |= add

geom = [bm.faces[i] for i in bad]
bmesh.ops.delete(bm, geom=geom, context="FACES")
bmesh.update_edit_mesh(o.data)

# report the boundary loops the cut left behind
bm = bmesh.from_edit_mesh(o.data)
bm.edges.ensure_lookup_table()
op = [e for e in bm.edges if len(e.link_faces) < 2]
adj = collections.defaultdict(list)
for e in op:
    adj[e.verts[0].index].append(e); adj[e.verts[1].index].append(e)
seen = set(); loops = []
for e in op:
    if e.index in seen:
        continue
    stack = [e]; loop = []
    while stack:
        x = stack.pop()
        if x.index in seen:
            continue
        seen.add(x.index); loop.append(x)
        for v in x.verts:
            for y in adj[v.index]:
                if y.index not in seen:
                    stack.append(y)
    cs = [v.co for x in loop for v in x.verts]
    n = len(cs)
    ctr = [round(sum(c[k] for c in cs) / n, 4) for k in range(3)]
    closed = all(len(adj[v.index]) == 2 for x in loop for v in x.verts)
    loops.append({"edges": len(loop), "center": ctr, "closed": closed})
loops.sort(key=lambda L: -L["edges"])

result = {"core_bad_faces": core, "deleted_with_buffer": len(bad),
          "faces_now": len(bm.faces), "verts_now": len(bm.verts),
          "boundary_loops": len(loops), "loops": loops}

