def inreg(c): return abs(c.x)<0.13 and c.y<-0.10 and 0.65<c.z<0.80
skip={"REBUILD_BAND","REBUILD_CHIN"}
skip_i={o.vertex_groups[n].index for n in skip if n in o.vertex_groups}
tot=nz=0
for v in o.data.vertices:
    if not inreg(v.co): continue
    tot+=1
    w=sum(g.weight for g in v.groups if g.group not in skip_i)
    if w<1e-6: nz+=1
result={"mouth_verts":tot,"with_NO_deform_weight":nz,
        "vgroups":len(o.vertex_groups)}

# MOUTH REBUILD - stage 4: give the new geometry its deform weights.
#
# The rebuilt faces were created by bmesh and carry NO vertex-group weights at
# all (861 of 1131 mouth verts). Unweighted verts simply do not follow the rig,
# so the mouth would tear open the moment the jaw moved.
#
# Weights are transferred from MOUTH_REF, the untouched copy, by nearest
# original vertex -- the original weighting scheme is preserved rather than
# invented. jaw_reweight.py then re-authors the lip line on top, which is the
# part that actually has to be right for the mouth to open.
from mathutils import kdtree

o = bpy.data.objects["clyffy_mesh"]
ref = bpy.data.objects["MOUTH_REF"]
if o.mode != "OBJECT":
    bpy.ops.object.mode_set(mode="OBJECT")

SKIP = {"REBUILD_BAND", "REBUILD_CHIN"}
skip_i = {o.vertex_groups[n].index for n in SKIP if n in o.vertex_groups}

# map ref group index -> live group (names match; the copy shares them)
ref_names = {g.index: g.name for g in ref.vertex_groups}

size = len(ref.data.vertices)
kd = kdtree.KDTree(size)
for i, v in enumerate(ref.data.vertices):
    kd.insert(v.co, i)
kd.balance()

fixed = 0
still = 0
for v in o.data.vertices:
    w = sum(g.weight for g in v.groups if g.group not in skip_i)
    if w > 1e-6:
        continue
    co, idx, dist = kd.find(v.co)
    src = ref.data.vertices[idx]
    got = False
    for g in src.groups:
        name = ref_names.get(g.group)
        if not name or name in SKIP or g.weight <= 0.0:
            continue
        grp = o.vertex_groups.get(name)
        if grp is None:
            grp = o.vertex_groups.new(name=name)
        grp.add([v.index], g.weight, "REPLACE")
        got = True
    if got:
        fixed += 1
    else:
        still += 1

def unweighted():
    n = 0
    for v in o.data.vertices:
        if abs(v.co.x) < 0.13 and v.co.y < -0.10 and 0.65 < v.co.z < 0.80:
            if sum(g.weight for g in v.groups if g.group not in skip_i) < 1e-6:
                n += 1
    return n

result = {"verts_weighted_from_ref": fixed, "no_source_found": still,
          "mouth_verts_still_unweighted": unweighted()}

