import bpy, json, math
from mathutils import Vector
o=bpy.data.objects["clyffy_mesh"]
if o.mode!="OBJECT": bpy.ops.object.mode_set(mode="OBJECT")
CORNER=0.078; GAP=0.0237
M=json.load(open("work/probes/pink_mask/upper_lip.json"))
import collections
pts=collections.defaultdict(list)
for c in M["centers"]: pts[round(c[0],2)].append(Vector(c))
border=[]
for x in sorted(pts):
    lo=min(pts[x],key=lambda v:v.z); border.append((x,lo.y,lo.z))
def upper_at(x):
    xs=[b[0] for b in border]; x=max(min(x,xs[-1]),xs[0])
    for i in range(len(border)-1):
        a,b=border[i],border[i+1]
        if a[0]<=x<=b[0]:
            t=0.0 if b[0]==a[0] else (x-a[0])/(b[0]-a[0])
            return (a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t)
    return (border[-1][1],border[-1][2])
def lens(th):
    x=CORNER*math.cos(th); y,zu=upper_at(x)
    taper=max(0.0,1.0-(x/CORNER)**2)
    return Vector((x,y,zu if math.sin(th)>=0 else zu-GAP*taper)), taper, (math.sin(th)>=0)
curve=[lens(2*math.pi*i/400) for i in range(400)]
up=[]; lo=[]
for v in o.data.vertices:
    c=v.co
    if not (abs(c.x)<0.11 and -0.30<c.y<-0.15 and 0.68<c.z<0.79): continue
    best=min(curve,key=lambda t:(t[0]-c).length)
    if (best[0]-c).length<0.006:
        (up if best[2] else lo).append((v.index,best[1]))
result={"upper_lip_verts":len(up),"lower_lip_verts":len(lo),
        "lower_taper_range":[round(min(t for _,t in lo),3),round(max(t for _,t in lo),3)] if lo else None}

