import bpy
was={}
for ob in bpy.data.objects:
    if ob.type=="EMPTY": was[ob.name]=ob.hide_viewport; ob.hide_viewport=True
parts=[ob for ob in bpy.data.objects if ob.type=="MESH" and not ob.hide_render
       and any(k in ob.name.lower() for k in ("teeth","tongue"))]
def move(dy,dz):
    for ob in parts:
        for v in ob.data.vertices: v.co.y+=dy; v.co.z+=dz
out={}
cur=0.0
for dy in (0.030,0.020,0.010):
    move(dy,0.0); cur+=dy
    out[f"dy_total_{round(cur,3)}"]=shot(f"TRY_dy{int(cur*1000)}",
        at=(0.0,-0.22,0.730), dist=0.17, yaw=0, pitch=34, overlays=False)
for n,v in was.items(): bpy.data.objects[n].hide_viewport=v
result={"shots":out,"total_dy":round(cur,3)}

import bpy, bmesh
rows=[]
for ob in bpy.data.objects:
    if ob.type!="MESH" or "teeth" not in ob.name.lower() or ob.hide_render: continue
    bm=bmesh.new(); bm.from_mesh(ob.data); bm.faces.ensure_lookup_table()
    seen=set(); n=0
    for f in bm.faces:
        if f.index in seen: continue
        n+=1; stack=[f.index]
        while stack:
            x=stack.pop()
            if x in seen: continue
            seen.add(x)
            for e in bm.faces[x].edges:
                for g in e.link_faces:
                    if g.index not in seen: stack.append(g.index)
    rows.append({"part":ob.name,"islands":n,"faces":len(bm.faces),
                 "verdict":"continuous band" if n==1 else f"{n} separate teeth (SPEC says WRONG)"})
    bm.free()
result={"teeth":rows}

